    paragraph3: 'PPV इवेंट शुरू करो, सब्सक्रिप्शन या पेड मैसेज से कमाओ, Watch2Earn अनुभव बनाओ दर्शक बढ़ाने या मौजूदा कम्युनिटी को इनाम देने के लिए, या एक्सक्लूसिव टोकन-गेटेड कंटेंट बाँटो — सब पारंपरिक बैंकिंग या KYC प्रक्रिया के बिना। तुम्हारा कंटेंट, तुम्हारे नियम, तुम्हारी कमाई।',
    paragraph4: 'लाखों क्रिएटर्स के साथ जुड़ो जो विकेंद्रीकृत ऐप्स पर कल की यूज़र-मालिकाना अर्थव्यवस्था बना रहे हैं, जहाँ मूल्य सीधे उनको जाता हैगा जो बनाते हैं — कॉर्पोरेट गेटकीपर्स और एल्गोरिदमिक मैनिपुलेशन से पूरी तरह आज़ाद।',
