    paragraph6: 'देखने को तैयार हो कि हम डिजिटल कंटेंट कैसे बदल रहे? हमारा टेक्निकल इंफ्रास्ट्रक्चर देखो और उन dApps को खोजो जो इस क्रिएटर रिनेसाँ को चला रहे हैं।',
    disclaimerTitle: 'महत्वपूर्ण सूचना',
    disclaimerText: 'DeHub टोकन हमारे इकोसिस्टम में यूटिलिटी टोकन के रूप में काम करते हैं, इन-गेम करेंसी की तरह, और निवेश का साधन नइ हैं। जबकि हमारा ब्लॉकचेन इंफ्रास्ट्रक्चर शैक्षिक उद्देश्यों के लिए अभूतपूर्व पारदर्शिता और सत्यापन योग्य ऑन-चेन डेटा देता हैगा, सभी बाज़ारों में अंतर्निहित जोखिम होते हैं। बाज़ार की अस्थिरता, तकनीकी समस्याओं, सुरक्षा उल्लंघनों या अप्रत्याशित परिस्थितियों के कारण तुम अपना पूरा निवेश खो सकते हो। केवल उन फंड से भाग लो जो पूरी तरह खोने की क्षमता हो। DeHub और इसके सहयोगी किसी भी वित्तीय नुकसान की ज़िम्मेदारी नइ लेते।',
