    accountsB3: 'मौजूदा वॉलेट:',
    accountsB3Desc: 'मेटामास्क, रेनबो, ट्रस्ट, फैंटम या कुछ भी WalletConnect से जुड़ें, और पता साबित करने के लिए एक बार हस्ताक्षर करें। अगर किसी फ़ैंटम साइन - इन को इसलिए मना कर दिया जाता है क्योंकि उसके एथेरियम पते का कोई इतिहास नहीं है, तो आप इसके बजाय अपना सोलाना वॉलेट साबित कर सकते हैं। वॉलेट यूज़र अपनी गैस का भुगतान खुद करते हैं।',
    accountsB4: 'कई प्रोफ़ाइल:',
    accountsB4Desc: 'सेटिंग → प्रोफ़ाइल में कई अकाउंट एक साथ रखें और लॉग आउट और बैक इन किए बिना स्विच करें। आपका बैज टियर तय करता है कि आप कितने लोगों को पकड़ सकते हैं।',
    accountsB5: 'नए सदस्य:',
    accountsB5Desc: 'हर कोई जो नए सदस्यों की निर्देशिका में शामिल होता है और अपने पहले तीस दिनों के लिए अपने नाम के बगल में एक नया सदस्य चिप रखता है, इसलिए समुदाय उन्हें देख सकता है और उनका स्वागत कर सकता है। नए सदस्यों को एक वैकल्पिक निर्देशित वॉकथ्रू भी प्रदान किया जाता है, जिसे बाद में सेटिंग से फिर से खोला जा सकता है।',
    accountsB6: 'पासकी:',
    accountsB6Desc: '"फ़िंगरप्रिंट के साथ जारी रखें" चुनें और पासकी ही अकाउंट है — कोई ईमेल नहीं, कोई फ़ोन नंबर नहीं, कोई पासवर्ड नहीं। वही पासकी वेबसाइट पर और एंड्रॉइड ऐप में काम करती है।',
