    feedsSoundtrack: 'फ़ोटो साउंडट्रैक:',
    feedsSoundtrackDesc: 'एक फ़ोटो पोस्ट में गाना जोड़ा जा सकता है। यह एक छोटे ग्लास कैप्सूल के रूप में दिखता है जो फ़ोटो के नीचे एक वेव में खुलता है, सीधे फीड से चलता है, और आगे-पीछे करने के लिए ड्रैग किया जा सकता है। गाने वाली फ़ोटो शॉर्ट्स में खुलती हैं; साधारण फ़ोटो अपनी पोस्ट में खुलती हैं।',
