    frontendLabel: 'प्लेबैक',
    govLiveDesc: 'ऊपर दिया गया डिज़ाइन है कि गवर्नेंस किस लिए है; गवर्नेंस पेज वह जगह है जहाँ ऐसा होता है। प्रस्तावों को प्रस्तावों के तहत सूचीबद्ध किया जाता है, पारित और अस्वीकृत किया जाता है, प्रत्येक अपने लेखक, उसके पाठ और जहां वोट खड़ा होता है। एक प्रस्ताव खोलने पर 10,000 DeHub टोकन का शुल्क लगता है, जिसकी पुष्टि श्रृंखला पर की जाती है, और प्रत्येक प्रस्ताव का थ्रेडेड चर्चा के साथ अपना पृष्ठ होता है। मतदान मुफ्त है: आपका वोट आपके बैज से भारित होता है, मतदान सात दिनों तक चलता है, और एक प्रस्ताव कम से कम दस अलग - अलग पर्स वोटिंग के साथ भारित बहुमत पर पारित होता है, इसलिए कोई भी एकल धारक ऐसा कुछ पारित नहीं कर सकता है जिसे किसी ने नहीं देखा हो।',
    govLiveTitle: 'प्रस्तावों पर मतदान',
