    miniAppsB3: 'एक बनाएँ:',
    miniAppsB3Desc: 'कोई भी वेबसाइट एक स्क्रिप्ट टैग के साथ एक मिनी ऐप बन जाती है। dehub.io/apps/dev आपके मैनिफ़ेस्ट की जाँच करता है, आपके फ़ीड कार्ड का पूर्वावलोकन करता है और किसी और को देखने से पहले ऐप को DeHub के अंदर चलाता है। फ़ार्केस्टर मिनी ऐप वैसे ही काम करते हैं जैसे वे हैं।',
