    miniAppsB4Desc: 'हर ऐप को वेरीफ़ाइड, रिव्यू नहीं किया गया या डेवलपर प्रीव्यू के रूप में चिह्नित किया गया है, ताकि आपको पता चल सके कि आप क्या खोल रहे हैं।',
    miniAppsDesc: 'ऐप, मेनू में और dehub.io/apps पर, किसी के द्वारा DeHub के लिए बनाए गए मिनी ऐप का एक स्टोर है। DeHub के अंदर एक मिनी ऐप केवल DeHub ड्रॉ करने वाले हेडर के नीचे खुलता है, आप पहले से ही साइन इन हैं, और हर ऐप अपना असली वेब पता दिखाता है।',
    miniAppsTitle: 'मिनी ऐप्स',
