    moreB3: 'स्टैट्स:',
    moreB3Desc: 'लाइव साइट की सांख्यिकी — दिन, वर्ष या सभी समय के लिए आगंतुक, पेज व्यू और समुदाय की संख्या — प्रकाशित की जाती है, न कि आंतरिक रूप से रखी जाती है। उसी पेज पर देहब की आय और लागत दिखाई जाती है, जो दैनिक आय के कुल और हमारे प्रदाताओं द्वारा दर्ज किए गए वास्तविक लागत से बनाई जाती है, ताकि आय और लागत दोनों पब्लिक हों जितनी ही ट्रैफिक है।',
    moreB4: 'लीडरबोर्ड और टॉप 100:',
    moreB4Desc: 'ऐड रेवेन्यू शेयर करने वाले क्रिएटर की रैंकिंग और प्लैटफ़ॉर्म के टॉप सौ अकाउंट.',
    moreB5: 'क्रिएटर :-',
    moreB5Desc: 'अभी - अभी आए सभी लोगों के नए सदस्यों के रोस्टर के साथ, क्रिएटर्स की एक डायरेक्टरी ढूँढने और फ़ॉलो करने के लिए.',
    moreB6: 'AI एजेंट और प्रॉम्प्ट:',
    moreB6Desc: 'ऐसे एजेंट तैनात करें जो आपकी ओर से काम करते हैं, और एक प्रश्न के साथ सीधे सहायक के पास जाने के लिए एक त्वरित सतह।',
