    msg11: 'ऑप्ट - इन ऑनलाइन स्टेटस: हरे रंग का डॉट सिर्फ़ तभी दिखाई देता है, जब आप उसे शेयर करना चुनते हैं',
    msg4: 'फ़ोटो, वीडियो, GIF और पेस्ट की गई फ़ोटो',
