    multipostB2: 'क्रेडिट पोस्ट करें:',
    multipostB2Desc: 'हर डिलीवरी हर प्लैटफ़ॉर्म पर क्रेडिट खर्च करती है, जिसकी कीमत उस प्लैटफ़ॉर्म तक पहुँचने के लिए तय की जाती है। क्रेडिट DeHub टोकन के साथ खरीदे जाते हैं, बड़े बंडलों पर छूट के साथ, और जब आप पोस्ट करते हैं तो आपके पास जो भी कम होता है वह खरीदा जाता है।',
    multipostB3: 'शेड्यूलिंग:',
