    multipostDesc: 'DeHub पर और उसी चरण में अपने अन्य सामाजिक खातों पर प्रकाशित करें। सेटिंग मल्टी - पोस्ट में एक बार खातों को → कनेक्ट करें, फिर संगीतकार में क्रॉस - पोस्ट आइकन से प्रत्येक पोस्ट को चुनें। DeHub पोस्ट का घर है; प्रतियां इसे उन दर्शकों तक ले जाती हैं जो आपके पास पहले से ही कहीं और हैं।',
    multipostTitle: 'हर जगह एक बार में पोस्ट करें',
