    nft2: 'अन्य टोकन से भुगतान करें और वे आपके लिए परिवर्तित हो जाते हैं',
    nft3: 'क्रिएटर को सीधे उनके वॉलेट में भुगतान किया जाता है',
    nftIntegration: 'भुगतान कैसे काम करता है',
    notificationsB1: 'चुनें कि आप तक क्या पहुँचता है:',
    notificationsB1Desc: 'सेटिंग में हर श्रेणी की प्राथमिकताएँ तय करती हैं कि क्या भेजा जाता है, ताकि आप सुझाव और ड्रॉप रिएक्शन रख सकें। टैब को गतिविधि के हिसाब से रैंक किया जाता है, हर टैब की अपनी अपठित संख्या दिखाई देती है और आप हर घंटे कितने लोगों के आने की सीमा तय करके सार्वजनिक चैट अलर्ट में शामिल हो सकते हैं।',
    notificationsB2: 'वेब और मोबाइल पर पुश करें:',
    notificationsB2Desc: 'दोनों ऐप डिवाइस पर ही पुश डिलीवर करते हैं — ब्राउज़र एक बार अनुमति मांगता है, एंड्रॉइड ऐप इंस्टॉल पर पूछता है — और सब कुछ किसी भी तरह से नोटिफ़िकेशन सेंटर में उतरता है।',
    notificationsB3: 'घोषणाएँ:',
