    notificationsB4: 'ईमेल द्वारा:',
    notificationsB4Desc: 'एक ईमेल पते को लिंक करें और आपके द्वारा चुनी गई श्रेणियाँ भी आपके इनबॉक्स में आती हैं, जो ऐप बंद होने के दौरान उन चीज़ों को पकड़ती हैं जिन्हें आप मिस नहीं करना चाहते हैं।',
    notificationsB5: 'टेक्स्ट के आधार पर:',
    notificationsB5Desc: 'टेक्स्ट मैसेज एक पेड चैनल हैं। इसे एक बार अनलॉक करें, एक नंबर वेरिफ़ाई करें, एक छोटा सा बैलेंस रखें और चुनें कि आपने हर नोटिफ़िकेशन को टेक्स्ट के ज़रिए ऑन किया है या सिर्फ़ पैसे से जुड़ी नोटिफ़िकेशन को। स्विच में एक संदेश की कीमत और शेष राशि पर क्या बचा है, क्योंकि एक टॉगल जो चुपचाप खर्च करना शुरू कर देता है वह एक ऐसी चीज है जो कभी नहीं होनी चाहिए।',
    notificationsB6: 'बैज:',
    notificationsB6Desc: 'घंटी आपको बताती है कि आपका बैज टियर कब ऊपर या नीचे जाता है और कब कोई आपको अपना बैज उधार देने की पेशकश करता है, और हर नोटिफ़िकेशन उसके पीछे मौजूद व्यक्ति का बैज दिखाता है।',
    notificationsDesc: 'आपके साथ जो कुछ भी होता है वह एक अधिसूचना केंद्र में उतरता है, टैब में विभाजित होता है ताकि उत्तर भुगतान को दफन न करें। आपके पोस्ट, नए फ़ॉलोअर्स, टिप्स और खरीदारी, स्टेज रिमाइंडर और आपके द्वारा बुक किए गए एक चरण के लाइव होने, सामुदायिक गतिविधि, और एक अलर्ट जब आपने अनुरोध बोर्ड पर एक सुविधा के लिए कहा है, तो वास्तव में जहाज — सभी एक ही स्थान पर, जो भी अधिसूचना के बारे में है उसके थंबनेल के साथ, ताकि आप उन्हें एक नज़र में अलग बता सकें।',
    notificationsTitle: 'नोटिफ़िकेशन',
    packsB1: 'पैक बनाएँ :-',
    packsB1Desc: 'इमोजी, स्टिकर या GIF पैक बनाने के लिए फ़ोटो अपलोड करें या लिंक पेस्ट करें। ऊँचे बैज वाले लेवल पर हर लेवल पर ज़्यादा पैक और ज़्यादा जगह मिलती है।',
    packsB2: 'इसे साझा करें:',
    packsB2Desc: 'हर पैक का dehub.io/packs पर अपना एक पेज होता है, जिसमें शेयर करने के लिए एक लिंक होता है, और सबसे ज़्यादा ऐड किए गए पैक ब्राउज़ करने के लिए सभी के लिए लिस्ट किए जाते हैं।',
    packsDesc: 'इमोजी पिकर में हर इमोजी होता है, जिसमें खोज, स्किन टोन और रीकेंट्स होते हैं, और अन्य ऐप के इमोजी इनलाइन होते हैं। इसके अलावा, बैज होल्डर अपने खुद के इमोजी, स्टिकर और GIF पैक बनाते हैं, और कोई भी अपने पिकर में एक साझा पैक जोड़ सकता है और चैट, टिप्पणियों और प्रतिक्रियाओं में इसका उपयोग कर सकता है।',
    packsTitle: 'इमोजी, स्टिकर और पैक',
