    spOpenToAll: 'हर अकाउंट के लिए खोलें',
    spPowersLead: 'बैज सीढ़ी का प्रत्येक पायदान बिल्कुल एक शक्ति को अनलॉक करता है, और आपके द्वारा अनलॉक की गई हर शक्ति अनलॉक की जाती है। वे सभी एक ही पाक्षिक भत्ते पर आकर्षित होते हैं, इसलिए विकल्प यह है कि इसे किस पर खर्च करना है।',
    spPowersTitle: 'बारह शक्तियाँ',
    spQuantityOnly: 'अधिक पहुंच, कोई नई शक्ति नहीं',
    spRotationDesc: 'स्लॉट पिन के बजाय घूमता है। जब कई बूस्ट एक साथ चल रहे होते हैं, तो प्रत्येक दर्शक को एक से निपटाया जाता है, जिसे बूस्टर के बैज टियर द्वारा भारित किया जाता है — एक उच्च स्तर को अधिक बार दिखाया जाता है, और सभी को अभी भी वह खिड़की मिलती है जिसके लिए उन्होंने भुगतान किया था। बूस्ट क्या खरीदता है, यह मिनटों की एक निश्चित संख्या के लिए आवाज का एक हिस्सा है, न कि फ़ीड के शीर्ष पर एकमात्र कब्जा।',
    spRotationTitle: 'स्लॉट कैसे शेयर किया जाता है',
    spSafetyDesc: 'प्रत्येक ड्रॉ को पोस्ट के खिलाफ फिर से जांचा जाता है क्योंकि यह उस पल में खड़ा होता है, इसलिए एक पोस्ट जिसे हटा दिया गया है, अवरुद्ध किया गया है या परिपक्व चिह्नित किया गया है, कभी भी किसी अजनबी के फ़ीड तक नहीं पहुंचता है। बुकिंग के दौरान भी परिपक्व पदों को अस्वीकार कर दिया जाता है, और किसी ऐसे व्यक्ति को बढ़ावा नहीं दिया जाता है जिसने आपको या आपके द्वारा बढ़ावा दिए गए व्यक्ति को अवरुद्ध कर दिया है।',
    spSafetyTitle: 'बूस्ट क्या नहीं कर सकता',
