    tipDesc1: 'हमारी इंटीग्रेटेड टिपिंग सर्विसेज़ सभी अपलोड और लाइव स्ट्रीम पर सिर्फ़ 10% फ़ीस लगाती हैं, TikTok जैसे लीडर्स के 60% की तुलना में, और वीडियो कैंसलेशन पर वोट करने की क्षमता भी हैगा जो पावर वापस व्यूअर्स के हाथ में देती हैगा।',
    tipDesc2: 'क्रिएटर्स को मिले टिप्स और व्यूअर्स द्वारा दिए गए टिप्स अलग लीडरबोर्ड में लॉग होते हैं व्यू काउंट और सब्सक्राइबर्स के साथ जो ऐड रेवेन्यू शेयर तय करते हैं। DeHub टोकन स्टेकहोल्डर्स को ओवरऑल प्रोटोकॉल प्रॉफ़िट का उनका हिस्सा मिलता हैगा।',
    mineTitle: 'कंटेंट मॉडरेशन से माइन करो',
