    mineDesc1: 'केवल कुछ वॉलेट में 50 मिलियन से अधिक DeHub टोकन हैं, जिनमें से अधिकांश परिचालन वॉलेट हैं, शेष ज्ञात समुदाय के सदस्य हैं।',
    mineDesc2: 'सिर्फ़ कोर टीम या टॉप टियर बैज होल्डर्स के पास वीडियो तुरंत हटाने की पावर होगी NFT बर्न करके। बाद में, सारी ऐड रेवेन्यू और कोई भी प्ले-टू-अर्न बाउंटी सभी वोटिंग वॉलेट में शेयर होंगी।',
    mineDynamic: 'सभी उपयोगिता के लिए आवश्यक DeHub टोकन की मात्रा एक गतिशील चर है, इसलिए मूल्य के संबंध में किसी भी समय बदला जाना चाहिए। किसी भी बदलाव की घोषणा सभी आधिकारिक चैनलों पर सार्वजनिक रूप से की जाएगी।',
