    introDesc2: 'चूंकि आगे आवंटन अब गतिशील होगा, प्रोटोकॉल शुल्क पर निर्भर करेगा, पदनाम किसी भी समय आवश्यकताओं के अधीन होंगे यह सुनिश्चित करना कि प्रोटोकॉल की जरूरतें हर समय सबसे आगे हैं। स्टेकिंग प्रोटोकॉल को भी वर्तमान में अपग्रेड किया जा रहा है और जल्द ही बेस पर रिलीज़ किया जाएगा।',
    restakeDesc: 'यूज़र फ़सल काटने के दौरान ऑटोमैटिक या मैन्युअल रीस्टैकिंग चुन सकते हैं। ऑटोमैटिक रीस्टाकिंग के लिए, बस रीस्टाक बटन पर क्लिक करें और चेन पर मैजिक के सामने आने पर देखें। मैन्युअल प्रक्रिया के लिए, बस अनस्टेक करें, थोड़ी देर के लिए अपने मेटामास्क के साथ खेलें और फिर मूल स्टेकिंग प्रक्रिया का पालन करें।',
