    q1: 'DeHub क्या हैगा?',
    a1: 'DeHub X, Facebook, YouTube और Rumble जैसे पुराने मीडिया ऐप्स का डिसेंट्रलाइज़्ड, यूज़र-मालिकाना विकल्प हैगा, जो ब्लॉकचेन टेक्नोलॉजी की एडवांसमेंट का इस्तेमाल करके यूज़र्स को संभावनाओं की एक पूरी नई दुनिया देता हैगा।',
    q2: 'DeHub टोकन का उपयोग किस लिए किया जाता है?',
    a2: 'DeHub टोकन पूरे DeHub पारिस्थितिकी तंत्र में उपयोगिता प्रदान करते हैं जिसमें गेम और सामग्री तक पहुंच, वैश्विक लेनदेन, रचनाकारों को टिप देना, NFT मार्केटप्लेस पर खरीदारी, शासन मतदान, पुरस्कारों के लिए दांव लगाना और नेटवर्क सुरक्षा शामिल हैं।',
    q3: 'DeHub का गवर्नेंस सिस्टम कैसे काम करता?',
    q4: 'मैं DeHub टोकन कहाँ से खरीद सकता/सकती हूँ?',
    a4: "DeHub टोकन (DHB) विभिन्न एक्सचेंजों पर उपलब्ध हैं। समर्थित एक्सचेंजों और ट्रेडिंग जोड़े की सबसे अद्यतित सूची के लिए हमारे 'कहां खरीदें' अनुभाग की जांच करें।",
    q5: 'मैं DeHub टोकन को कैसे ब्रिज करूँ?',
    a5: 'आप हमारे टोकन ब्रिज का उपयोग करके आधार और बीएनबी श्रृंखलाओं के बीच DeHub टोकन को पुल कर सकते हैं। विस्तृत निर्देशों, ब्रिज पतों और प्रोसेसिंग समय के लिए हमारे दस्तावेज़ीकरण में टोकन ब्रिज सेक्शन पर जाएँ। बस उपयुक्त ब्रिज पते की प्रतिलिपि बनाएं और चरण - दर - चरण प्रक्रिया का पालन करें।',
    q6: 'क्या मैं DeHub टोकन दांव पर लगा सकता हूँ?',
    a6: 'हां, आप प्रोटोकॉल राजस्व बायबैक और x -2 - अर्जित पुरस्कारों से वास्तविक उपज अर्जित करने के लिए DeHub टोकन दांव पर लगा सकते हैं। स्टेकिंग नेटवर्क को सुरक्षित करने में भी मदद करता है और पारिस्थितिकी तंत्र के भीतर उन्नत अधिकार प्रदान करता है।',
    q7: 'DeHub पर कौन से गेम अवेलेबल हैं?',
    q8: 'DePIN इंफ्रास्ट्रक्चर कैसे काम करता?',
    a8: 'DeHub का DePIN यूज़र्स को कंप्यूटिंग रिसोर्स कंट्रीब्यूट करने और रिवार्ड कमाने देता जबकि डिसेंट्रलाइज़्ड इंफ्रास्ट्रक्चर नेटवर्क बनाने में मदद करता।',
    q9: 'DeHub के AI टूलकिट क्या हैं?',
    a9: "हमारे AI टूलकिट डेवलपर्स और यूज़र्स को DeHub इकोसिस्टम में इंटीग्रेटेड एडवांस्ड AI-पावर्ड टूल और सर्विसेज़ देते हैं, d'Apps और गेम में फ़ंक्शनैलिटी बढ़ाते।",
    q10: 'DeHub पर एडवर्टाइज़िंग कैसे काम करती?',
    a10: 'DeHub एक विकेन्द्रीकृत विज्ञापन प्लेटफ़ॉर्म प्रदान करता है जहां विज्ञापनदाता अभियान बना सकते हैं, विशिष्ट दर्शकों को लक्षित कर सकते हैं, और DeHub टोकन के साथ भुगतान कर सकते हैं। कॉन्टेंट क्रिएटर प्रासंगिक विज्ञापन दिखाने के लिए रिवॉर्ड कमा सकते हैं.',
    q11: 'क्या DeHub सिक्योर हैगा?',
    a11: 'हाँ, DeHub ने CertiK से सिक्योरिटी ऑडिट करवाए हैं और बग बाउंटी प्रोग्राम मेंटेन करता। हम सभी स्मार्ट कॉन्ट्रैक्ट और इंफ्रास्ट्रक्चर में सिक्योरिटी प्रायोरिटी करते हैं।',
    q12: 'DeHub टोकन की कुल आपूर्ति क्या है?',
    a12: 'DeHub कॉन्ट्रोल्ड एमिशन और बायबैक मैकेनिज़म के साथ ध्यान से डिज़ाइन किया गया टोकनोमिक्स मॉडल फ़ॉलो करता। डिटेल्ड सप्लाई इनफ़ॉर्मेशन और डिस्ट्रिब्यूशन शेड्यूल के लिए हमारा Token Economics सेक्शन देखो।',
    q13: 'DeHub गवर्नेंस में कैसे भाग लें?',
    q14: 'DeHub टोकन रखने के क्या लाभ हैं?',
    a14: 'फायदों में एन्हांस्ड फ़ीचर्स एक्सेस, ग्लोबल ट्रांज़ैक्शन, क्रिएटर टिपिंग, NFT मार्केटप्लेस खरीदारी, गवर्नेंस राइट्स, स्टेकिंग रिवार्ड, नेटवर्क सिक्योरिटी भागीदारी और फ्यूचर यूटिलिटी एक्सपैंशन शामिल।',
    q15: 'क्या DeHub पर कंटेंट क्रिएटर्स को टिप दे सकते?',
